data = open(path, 'rb').read()

def get_obj(num):
    m = re.search((r'\n%d 0 obj\n' % num).encode(), data)
    if not m: return None
    start = m.end()
    end = data.find(b'endobj', start)
    return data[start:end]

def get_stream_decompressed(body):
    sm = re.search(rb'stream\r?\n', body)
    if not sm: return None
    raw_start = sm.end()
    raw_end = body.find(b'endstream')
    raw = body[raw_start:raw_end]
    if b'/FlateDecode' in body:
        try:
            return zlib.decompress(raw)
        except Exception as e:
            return None
    return raw

def parse_cmap(cmap_text):
    mapping = {}
    for m in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', cmap_text):
        code = int(m.group(1), 16)
        uni = m.group(2)
        # unicode could be multi-byte hex (utf-16be)
        uni_bytes = bytes.fromhex(uni.decode())
        try:
            ch = uni_bytes.decode('utf-16-be')
        except Exception:
            ch = ''
        mapping[code] = ch
    # bfrange with array not handled here (rare); simple range handled by regex above? Actually bfrange lines look like <lo><hi><dstlo>
    for m in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', cmap_text):
        lo = int(m.group(1),16); hi = int(m.group(2),16); dstlo = int(m.group(3),16)
        for i, code in enumerate(range(lo, hi+1)):
            mapping[code] = chr(dstlo + i)
    return mapping

fonts = {'F1':10, 'F2':16, 'F4':28}
cmaps = {}
for name, num in fonts.items():
    body = get_obj(num)
    tu = re.search(rb'/ToUnicode\s+(\d+)\s+0\s+R', body)
    if tu:
        cbody = get_obj(int(tu.group(1)))
        s = get_stream_decompressed(cbody)
        cmaps[name] = parse_cmap(s)
    else:
        cmaps[name] = {}

content_body = get_obj(2077)
content = get_stream_decompressed(content_body)
print(len(content))

# parse content stream: track Tf for current font, and Tj/TJ operators
text_out = []
cur_font = None
i = 0
tokens = re.finditer(rb'/(F\d)\s+[\d.]+\s+Tf|<([0-9A-Fa-f]+)>\s*Tj|\[(.*?)\]\s*TJ', content, re.DOTALL)
for m in tokens:
    if m.group(1):
        cur_font = m.group(1).decode()
    elif m.group(2):
        hexstr = m.group(2)
        cm = cmaps.get(cur_font, {})
        s=''
        for j in range(0, len(hexstr), 4):
            code = int(hexstr[j:j+4], 16)
            s += cm.get(code, '')
        text_out.append(s)
    elif m.group(3) is not None:
        arr = m.group(3)
        cm = cmaps.get(cur_font, {})
        s = ''
        for hm in re.finditer(rb'<([0-9A-Fa-f]+)>', arr):
            hexstr = hm.group(1)
            for j in range(0, len(hexstr), 4):
                code = int(hexstr[j:j+4], 16)
                s += cm.get(code, '')
        text_out.append(s)

print(' '.join(text_out))
